INSERT INTO feature VALUES('multi-output-data','types','Multi-output data constructors','nominal-data','partial','uncommon','dependent provers','A data constructor writes an output group, `| Share : (e : Expr) --> (left : Expr, right : Expr)`, read at grade ω as one port per output: an ordinary constructor over the shared inputs, at consecutive tags, so the core sees ordinary data. `Share(e).left` constructs a port and `Share(x).left` matches one, coverage counts each port and refines its index on its own, a data block''s rules name ports, and `Share(e)` is the record of the ports, a parameterised family''s typed by the record type its position states.','surface-grammar surface-lowering','corpus/ledger/features/multi-output-data.gandr crates/surface-lowering/src/lower/native/fixture/ports.gandr','corpus/ledger/features/multi-output-data.gandr','#4288');
